scwin.gCd041, scwin.gCd042, scwin.gCd043, scwin.gCd044, scwin.gCd045, scwin.gCd046, scwin.gCd047, scwin.gCd048, scwin.gCd061, scwin.gCd075, scwin.gCd076, scwin.gCd081, scwin.gCd084, scwin.gCd085, scwin.gCd089, scwin.gCd090, scwin.gCd097, scwin.gCd103, scwin.gCd104, scwin.gCd107; // 코스닥용
