scwin.gRsnYn = "N"; //처리절차 107 일때 매매거래정지 사유(20170120)
scwin.gEndYn = "N"; //처리절차 107 일때 매매거래정지 만료일시(20170120)

scwin.vScrenID = 'ULDSTF10007.xml';
scwin.gAskScrenID = ''; // 뷰어를 호출한 부모 화면ID KBoY 2017-10-16
