scwin.gAtsTrnsmYn = ""; //거래정지 해당여부(ATS 전송여부)
scwin.gAtsTrnsmRsltCd = ""; //ATS 전송 결과(S_성공,E_실패,E1_실패(공시뷰어를 닫지 않은 경우))
scwin.gBatchReservYn = "";
