}; //예약공시 여부(Y^20시이후,N^20시이전,^대상X)

scwin.fn_SetValue = function() {
    sessionStorage.setItem("gAttachDocYn", scwin.gAttachDocYn); //인쇄화면 파라메터 전달

    scwin.gTrdHaltMsg = "(경고) 동사 주권의 매매거래가 정지되지 않았음을 알려드립니다. " + "거래시간 중 '매매거래정지 안내' 및 '관련공시' 배포는 매매거래가 정지된 이후 처리되어야 합니다. " + "거래정지 여부를 확인하신 후에 처리하시기 바랍니다.";

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !접수문서의--;
정보;
셋팅-- > function() {
    $c.frame.path("../").fn_getParam();
    scwin.gAcptNo = $c.frame.path("../").scwin.gAcptNo;
    scwin.gOpenAcptNo = scwin.gAcptNo;
    scwin.gViewerStat = $c.frame.path("../").scwin.gViewerStat;
    scwin.gAskScrenID = $c.frame.path("../").scwin.gAskScrenID; // 뷰어를 호출한 부모 화면ID KBoY 2017-10-16
    if (scwin.gAskScrenID == "undefined") {
        //null 처리 20180112
        scwin.gAskScrenID = "";
    }
    scwin.gAccssAuthTpCd = $c.frame.path("../").scwin.gAccssAuthTpCd; // fn_OpenDisclViewer 에서 세팅해서 보냄 KBoY 2017-10-16
    if (scwin.gAccssAuthTpCd == "undefined") {
        //null 처리 20180112
        scwin.gAccssAuthTpCd = "01";
    }

    //임시
    txb_AcptNo.setValue(scwin.gAcptNo);
    //alert("자식창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};



// 주식선물/옵션대상 및 자산2조원여부 가져오기
scwin.fn_readEqytyOptBigYn = function() {
    if (scwin.gDoc_LdMktTp == '1' || scwin.gDoc_LdMktTp == '9') {
        // 기본정보조회
        var url = "/CorporationInfo.do?method=readCorpEqtyOptBigInfo&inputMessageId=CORP_BASICINFO_OUT" + "&outputMessageId=CORP_BASICINFO_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
        dts_corp_basic.DataID = encodeURI(url);
        dts_corp_basic.reset();
        $c.stf.showObj(panel_2, true);
    } else {
        $c.stf.showObj(panel_2, false);
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !접수정보--;
데이타;
읽어오기-- > function() {
    //alert("헤더읽어오기:"+gAcptNo);

    var url = "/Viewer.do?method=getDsclHeaderBasic&inputMessageId=VIEWER_OUT&outputMessageId=VIEWER_OUT" + "&ACPT_NO=" + scwin.gAcptNo + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_AcptProcs.DataID = encodeURI(url);
    dts_AcptProcs.reset();

    // 정정문서 history
    var url = "/Viewer.do?method=getDsclHeaderMainDoc&inputMessageId=VIEWER_DOCLIST_INOUT&outputMessageId=VIEWER_DOCLIST_INOUT" + "&ACPT_NO=" + scwin.gAcptNo;
    dts_MainDocHistory.DataID = encodeURI(url);
    dts_MainDocHistory.reset();

    //첨부문서 history		
    var url = "/Viewer.do?method=getDsclHeaderAttachDoc&inputMessageId=VIEWER_ATTACH_INOUT&outputMessageId=VIEWER_DOCLIST_INOUT" + "&ACPT_NO=" + scwin.gAcptNo + "&SCREN_ID=" + scwin.gAskScrenID + "&ACCSS_AUTH_TP_CD=" + scwin.gAccssAuthTpCd; // 비공개 첨부서류 표시여부 확인을 위해 뷰어를 호출한 부모 화면ID KBoY 2017-10-16
    dts_AttachDocHistory.DataID = encodeURI(url);
    dts_AttachDocHistory.reset();
};
scwin.fn_OnlyHeadRead = function() {
    var url = "/Viewer.do?method=getDsclHeaderBasic&inputMessageId=VIEWER_OUT&outputMessageId=VIEWER_OUT" + "&ACPT_NO=" + scwin.gAcptNo;
    dts_AcptProcs.DataID = encodeURI(url);
