    // ********************************************************************

};X < !서식에--;
해당하는;
공시알림;
메세지;
체크-- > function() {
    var url = "/DisclosureStudy.do?method=getAlertMsg&inputMessageId=DISCLSALERT_IN&outputMessageId=DISCLSALERT_OUT" + "&ACPT_NO=" + scwin.gAcptNo + "&ISUR_CD=" + scwin.gIsurCd + "&LD_MKT_TP_CD=" + scwin.gDoc_LdMktTp + "&FORM_UPCLSS_CD=" + scwin.gFromUpclssCd + "&MAINFORM_CD=" + scwin.gMainFormCd + "&FORM_VER=" + scwin.gFormVer + "&SNDLOC_TP_CD=" + scwin.gSndlocTpCd;
    dts_AlertInfo.DataID = encodeURI(url);
