scwin.fn_PrintOpen = async function() {
    //alert(gDocUrl : gDocUrl);
    var printType = scwin.gSndlocTpCd;
    var vFromUpclssCd = scwin.gFromUpclssCd;
    //alert("gPrintAcptNo:"+gPrintAcptNo);
    //alert("gPrintDocNo:"+gPrintDocNo);

    //인쇄화면 파라메터 전달
    sessionStorage.setItem("gDocUrl", scwin.gDocUrl);
    sessionStorage.setItem("gSndlocTpCd", scwin.gSndlocTpCd);
    sessionStorage.setItem("gFromUpclssCd", scwin.gFromUpclssCd);
    sessionStorage.setItem("gPrintAcptNo", scwin.gPrintAcptNo);
    sessionStorage.setItem("gPrintDocNo", scwin.gPrintDocNo);
    if (printType == '20' && vFromUpclssCd != '01') {
        // 수시공시는 제외
        var usrl = "/disclsdocviewer/pdfView.jsp?type=pdf" + "&acptNo=" + scwin.gPrintAcptNo + "&docNo=" + scwin.gPrintDocNo + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&docpath=" + scwin.gDocUrl;
        var winTitle = "공시뷰어";
        await $c.frame.CreateDialogFrame("testPop", usrl, winTitle, 10, 10, 900, 700, "window");
    } else {
        scwin.fn_PopupDocOpen();
    }
};



/*  인쇄하기 화면오픈  => 안씀 */
scwin.fn_PrintOpen2 = function() {
    var printType = scwin.gSndlocTpCd;
    var vFromUpclssCd = scwin.gFromUpclssCd;
    if (printType == '20' && vFromUpclssCd != '01') {
        // 수시공시는 제외
        var usrl = "/disclsdocviewer/filedownload_jws_start.jsp?type=pdf" + "&docpath=" + scwin.gDocUrl + ".htm";
        $c.frame.path("../").frame_hidden.srcUrl = usrl;
    } else {
        var usrp = "/Viewer.do?method=readDsclDocPrintContent" + "&ACPT_NO=" + scwin.gPrintAcptNo + "&DOC_NO=" + scwin.gPrintDocNo + "&FORM_CD=" + scwin.gPrintFormCd + "&FORM_VER=" + scwin.gPrintFormVer + "&VIEW_LANG_TP_CD=" + scwin.gViewLangTpCd + "&SUBMIT_SYS_TP_CD=" + scwin.gSubmitSysTp;
        window.open(usrp, "printform2", "left=0,top=0,width=800,height=600,resizable=yes,scrollbars=yes,location=no,status=no");
    }
};



