    scwin.gProcsStatCd = dts_AcptProcs.getCellData(1, "PROCS_STAT_CD");
    scwin.gIsurCd = dts_AcptProcs.getCellData(1, "ISUR_CD");
    scwin.gSndlocTpCd = dts_AcptProcs.getCellData(1, "SNDLOC_TP_CD");
    scwin.gDoc_LdMktTp = dts_AcptProcs.getCellData(1, "LD_MKT_TP_CD");
    scwin.gLangTpCd = dts_AcptProcs.getCellData(1, "LANG_TP_CD");
    scwin.gFromUpclssCd = dts_AcptProcs.getCellData(1, "FORM_UPCLSS_CD");
    var vDocNo = dts_AcptProcs.getCellData(1, "DISCLS_DOC_NO");
    scwin.gProcs_063 = dts_AcptProcs.getCellData(1, "FPROCS_063"); // 시장조치관련 - 영문자동변환대상 : count(*)
    scwin.gProcs_070 = dts_AcptProcs.getCellData(1, "FPROCS_070"); // 외국투자자를 위한 영문변환대상 : count(*)
    scwin.gSubmitSysTp = dts_AcptProcs.getCellData(1, "SUBMIT_SYS_TP_CD"); // 제출구문 - 한글자동변환 :0=국문제출, 1=영문제출	
    scwin.gSvcStatYn = dts_AcptProcs.getCellData(1, "SVC_STAT_YN"); // 외국투자자를 위한 서비스상태여부
    scwin.gProcs_111 = dts_AcptProcs.getCellData(1, "FPROCS_111"); // 웹폼영문서식 20180112
    scwin.gSecuGrpEF = dts_AcptProcs.getCellData(1, "SECUGRP_EF"); //ETF여부  20180112
    scwin.gDisclsEnYn = dts_AcptProcs.getCellData(1, "DISCLS_EN_YN"); //영문공시 존재 여부

    /*연계공시 개발*/
    scwin.gHdcomLnkDisclsYn = dts_AcptProcs.getCellData(1, "HDCOM_LNK_DISCLS_YN");
    scwin.gHdcomDisclsProcsStatCd = dts_AcptProcs.getCellData(1, "HDCOM_DISCLS_PROCS_STAT_CD");
    scwin.gSubcomDisclsProcsStatCd = dts_AcptProcs.getCellData(1, "SUBCOM_DISCLS_PROCS_STAT_CD");
    scwin.gSubcomNxtddTddTpCd = dts_AcptProcs.getCellData(1, "SUBCOM_NXTDD_TDD_TP_CD");

    /*사후심사현황 20151231*/
    scwin.gAffProcsStatCd = dts_AcptProcs.getCellData(1, "AFF_PROCS_STAT_CD");
    scwin.gAffProcsStatNm = dts_AcptProcs.getCellData(1, "AFF_PROCS_STAT_NM");

    /*부동산투자(RT) 20161125*/
    scwin.gSecuGrpRT = dts_AcptProcs.getCellData(1, "SECUGRP_RT");

    // 뷰어오픈시 최초 문서번호 셋팅
    if (scwin.gOpenAcptNo == scwin.gAcptNo && scwin.gChangeCnt == 0) {
        scwin.gOpenDocNo = vDocNo;
    }
    scwin.gDisclsDocNo = '';
    scwin.gMainFormCd = dts_AcptProcs.getCellData(1, "FORM_CD");
    scwin.gFormVer = dts_AcptProcs.getCellData(1, "FORM_VER");
    scwin.gNxtTpCd = dts_AcptProcs.getCellData(1, "NXTDD_TDD_TP_CD");
    scwin.gDisclsAcptTpCd = dts_AcptProcs.getCellData(1, "DISCLS_ACPT_TP_CD");
    scwin.gDisclsTrnsmTpCd = dts_AcptProcs.getCellData(1, "DISCLS_TRNSM_TP_CD");
    scwin.gDelayYn = dts_AcptProcs.getCellData(1, "DELAY_YN");
    scwin.gDelayFormYn = dts_AcptProcs.getCellData(1, "DELAY_FORM_YN");
    scwin.gLinitIsu = dts_AcptProcs.getCellData(1, "LIMIT_ISU");
    scwin.gListInvstgCondTpCd = dts_AcptProcs.getCellData(1, "LIST_INVSTG_COND_TP_CD");
    scwin.gListInvstgMiscTpCd = dts_AcptProcs.getCellData(1, "LIST_INVSTG_MISC_TP_CD");
    scwin.gPharmaBioComYn = dts_AcptProcs.getCellData(1, "PHARMA_BIO_COM_YN");
    scwin.gFormWarnContn = dts_AcptProcs.getCellData(1, "FORM_WARN_CONTN");
    scwin.gAtsIsuYn = dts_AcptProcs.getCellData(1, "ATS_ISU_YN");
    scwin.gMktclsYn = dts_AcptProcs.getCellData(1, "MKTCLS_YN");
    scwin.gAtsTrnsmYn = dts_AcptProcs.getCellData(1, "ATS_TRNSM_YN");
    scwin.gAtsTrnsmRsltCd = dts_AcptProcs.getCellData(1, "ATS_TRNSM_RSLT_CD");
    scwin.gBatchReservYn = dts_AcptProcs.getCellData(1, "BATCH_RESERV_YN");

    //alert(gAcptNo+","+  vDocNo+","+gMainFormCd+","+gFormVer);

    //인쇄화면 파라메터 전달 2022.04.29
    sessionStorage.setItem("gProcs_063", scwin.gProcs_063);
    sessionStorage.setItem("gProcs_070", scwin.gProcs_070);
    sessionStorage.setItem("gLangTpCd", scwin.gLangTpCd);
    sessionStorage.setItem("gSvcStatYn", scwin.gSvcStatYn);
    sessionStorage.setItem("gSubmitSysTp", scwin.gSubmitSysTp);
    sessionStorage.setItem("gProcs_111", scwin.gProcs_111);
    sessionStorage.setItem("gSecuGrpEF", scwin.gSecuGrpEF);
    sessionStorage.setItem("gDisclsEnYn", scwin.gDisclsEnYn);
    sessionStorage.setItem("gAcptNo", scwin.gAcptNo);
    sessionStorage.setItem("gSvrGubun", js_svrGubun);

    //기술특례여부 코스닥만 보이도록 20211126
    if (scwin.gDoc_LdMktTp == '2') {
        $c.stf.showObj(lbl_skil_specl, true);
        $c.stf.showObj(txt_skil_specl, true);
        if (scwin.gListInvstgCondTpCd == "2") {
            if (scwin.gListInvstgMiscTpCd == "2") {
                txt_skil_specl.setValue("이익미실현/외국기업");
            } else {
                txt_skil_specl.setValue("이익미실현기업");
            }
        } else if (scwin.gListInvstgCondTpCd == "3" || scwin.gListInvstgCondTpCd == "4" || scwin.gListInvstgCondTpCd == "5") {
            if (scwin.gPharmaBioComYn == "Y") {
                //제약ㆍ바이오			
                if (scwin.gListInvstgMiscTpCd == "2") {
                    txt_skil_specl.setValue("기술성장/제약ㆍ바이오/외국기업");
                } else {
                    txt_skil_specl.setValue("기술성장/제약ㆍ바이오기업");
                }
            } else {
                if (scwin.gListInvstgMiscTpCd == "2") {
                    txt_skil_specl.setValue("기술성장/외국기업");
                } else {
                    txt_skil_specl.setValue("기술성장기업");
                }
            }
        } else {
            // gListInvstgCondTpCd = '1' 이거나 '' 인경우 
            if (scwin.gListInvstgMiscTpCd == "2") {
                txt_skil_specl.setValue("일반/외국기업");
            } else {
                txt_skil_specl.setValue("일반기업");
            }
        }
    }
    scwin.fn_ShowLangBtn(scwin.gProcs_063, scwin.gProcs_070, scwin.gSubmitSysTp, scwin.gProcs_111, scwin.gDisclsEnYn); // 언어선택구분
