    } 
    */

    if (scwin.gOpenAcptNo == scwin.gAcptNo &&
        scwin.gOpenDocNo == vDocNo &&
        scwin.gChangeCnt == 0) {
        //alert( gOpenAcptNo+'=='+ gAcptNo +'&&'+ gOpenDocNo +'=='+ vDocNo +'&&'+  gChangeCnt );

        scwin.fn_getProcObjYn(); // 처리버튼 생성유무
        if (scwin.gSubmitSysTp == '0' && scwin.gLangTpCd == '1') {
            // 국문제출에서 제출한 영문공시를 디폴트로 볼때..
            scwin.fn_getDocHtmlURL(scwin.gAcptNo, vDocNo, scwin.gMainFormCd, scwin.gFormVer, '0', scwin.gSubmitSysTp);
        } else {
            scwin.fn_getDocHtmlURL(scwin.gAcptNo, vDocNo, scwin.gMainFormCd, scwin.gFormVer, scwin.gLangTpCd, scwin.gSubmitSysTp);
        }
    } else {

    }
    scwin.gChangeCnt++;
    if (scwin.gProcsStatCd == '00' || scwin.gProcsStatCd == '01' || scwin.gProcsStatCd == '02' ||
        scwin.gProcsStatCd == '10' || scwin.gProcsStatCd == '15' || scwin.gProcsStatCd == '20') {
        // 팀장 : 승인단계		
        // 공시 알림 경고사항 체크
        //fn_AlertCheck();	//alert창이 먼저뜨면 문서변환이 완료되도 표시가 안되어 완료로드 후로 이동 2011.03.23
        scwin.fn_getProcObjYn(); // 처리버튼 생성유무

    }
    if (scwin.gDisclsAcptTpCd == 'A' || scwin.gDisclsAcptTpCd == 'U') {
        scwin.setComboValue(cmb_maindoc, '', "DOC_NO");
        scwin.setComboValue(cmb_AttachDoc, vDocNo, "DOC_NO");
    }
    scwin.gReqObjAcptDocNo = dts_AcptProcs.getCellData(1, "REQ_OBJ_ACPT_DOC_NO"); //정정공시요구 대상 기공시 접수번호 (lds353 추가 20130313)
    scwin.gModReqRcvYn = dts_AcptProcs.getCellData(1, "MOD_REQ_RCV_YN"); //정정공시요구 받았는지에 대한 여부(기공시에 해당되는지 여부) (lds353 추가 20130313)

    scwin.gSectTpCd = dts_AcptProcs.getCellData(1, "SECT_TP_CD"); //소속부유형코드

    // 기공시조회 버튼 표출여부 
    //70970(코)
    //99840(유)
    //91691(채)
    if (scwin.gMainFormCd == '70970' || scwin.gMainFormCd == '99840' || scwin.gMainFormCd == '91691') {
        $c.stf.showObj(btn_mod_dscl_req_acpt, true);
    }
    if (scwin.gModReqRcvYn == 'Y') {
        if (scwin.gProcsStatCd == '30') {
            // 승인된 이후의 화면에서만 해당 경고창 발생
            var vAlert = "◆ 주의 사항 ◆\n\n" + "본 공시사항은 공시내용 기재 불충분 등의 사유로 한국거래소로부터 정정요구를 받은 사항입니다." + "\n동 공시에 대한 정정공시가 이루어지는 경우 공시내용의 기재내용이 달라지게 되므로 반드시 정정내용을 확인하시기 바랍니다.";
            //alert(vAlert);
            scwin.gAlertMsg = vAlert; // 경고메세지			
            setTimeout("alert(gAlertMsg)", 1000); //반드시 setTimeout 함수를 써야됨.

        }
    }
};
