scwin.cmb_maindoc_OnCloseUp = function() {
    scwin.gAttachDocYn = 'N';
    sessionStorage.setItem("gAttachDocYn", scwin.gAttachDocYn); //인쇄화면 파라메터 전달

    //<event for="cmb_maindoc" eventname="OnSelChange()" >
    var vDocNo = $c.cp.valueOfIndex(cmb_maindoc, "DOC_NO", cmb_maindoc.getSelectedIndex());
    scwin.gDisclsDocNo = vDocNo;

    //alert('m='+vDocNo+'=');
    if (vDocNo != '') {
        var vAcptNo = dts_MainDocHistory.getCellData(cmb_maindoc.getSelectedIndex() + 1, "ACPT_NO");
        var vFormCd = dts_MainDocHistory.getCellData(cmb_maindoc.getSelectedIndex() + 1, "FORM_CD");
        var vFormVer = dts_MainDocHistory.getCellData(cmb_maindoc.getSelectedIndex() + 1, "FORM_VER");
        var vProcsStatCd = dts_MainDocHistory.getCellData(cmb_maindoc.getSelectedIndex() + 1, "PROCS_STAT_CD");
        scwin.gAcptTpCd = '';

        /*
        if (gAcptNo !=  vAcptNo) {
        	// 헤더 변경
        	frame.Provider("../").gAcptNo = vAcptNo;			
        	gAcptNo = vAcptNo;
        	txb_AcptNo.value = vAcptNo;						
        	fn_OnlyHeadRead() ;
        	// 원문내용가져오기
        	// fn_getDocHtmlURL(vAcptNo, vDocNo, vFormCd, vFormVer);	
        } else {
        	// 원문내용가져오기
        	// fn_getDocHtmlURL(vAcptNo, vDocNo, vFormCd, vFormVer);	
        }
        */

        // 공시처리가 완료된것은 팝업으로 그외는 뷰어 가운데로 보여줌 
        // 2008.08.12 인수테스트시 : 김재홍, 허기영, 유재숙 합의함
        //alert('main='+gChangeCnt+', vProcsStatCd='+vProcsStatCd);
        if (vProcsStatCd == '30' || vProcsStatCd == '35' || vProcsStatCd == '40') {
            if (scwin.gOpenAcptNo != vAcptNo || scwin.gOpenDocNo != vDocNo &&
                scwin.gChangeCnt > 0) {
                scwin.fn_getDocHtmlURLPopup(vAcptNo, vDocNo, vFormCd, vFormVer, scwin.gLangTpCd, scwin.gSubmitSysTp);
            } else {
                // 바로 이전에 본 문서가 승인완료된것 아니면 팝업으로..
                if (scwin.gProcsStatCd == '00' || scwin.gProcsStatCd == '01' || scwin.gProcsStatCd == '02' ||
                    scwin.gProcsStatCd == '10' || scwin.gProcsStatCd == '15' || scwin.gProcsStatCd == '20') {
                    // 팀장 : 승인단계	
                    scwin.fn_getDocHtmlURLPopup(vAcptNo, vDocNo, vFormCd, vFormVer, scwin.gLangTpCd, scwin.gSubmitSysTp);
                }
            }
        } else {
            if (scwin.gAcptNo != vAcptNo) {
                // 헤더 변경
                $c.frame.path("../").scwin.gAcptNo = vAcptNo;
                scwin.gAcptNo = vAcptNo;
                txb_AcptNo.setValue(vAcptNo);
                scwin.fn_OnlyHeadRead();
            }
            scwin.fn_getProcObjYn(); // 처리버튼 생성유무
            scwin.fn_getDocHtmlURL(vAcptNo, vDocNo, vFormCd, vFormVer, scwin.gLangTpCd, scwin.gSubmitSysTp);
        }
        scwin.gSelectAtt = 'N';
        scwin.setComboValue(cmb_AttachDoc, '', "DOC_NO"); // 첨부문서 리스트 리셋		

    }
};
scwin.cmb_AttachDoc_OnCloseUp = function() {
    scwin.gAttachDocYn = 'Y';
    sessionStorage.setItem("gAttachDocYn", scwin.gAttachDocYn); //인쇄화면 파라메터 전달

    //<event for="cmb_AttachDoc" eventname="OnSelChange()" >
    var vDocNo = $c.cp.valueOfIndex(cmb_AttachDoc, "DOC_NO", cmb_AttachDoc.getSelectedIndex());
    //gDisclsDocNo = vDocNo;
    //alert('a='+vDocNo+'=');
    if (vDocNo != '') {
        var vAcptNo = dts_AttachDocHistory.getCellData(cmb_AttachDoc.getSelectedIndex() + 1, "ACPT_NO");
        var vFormCd = dts_AttachDocHistory.getCellData(cmb_AttachDoc.getSelectedIndex() + 1, "FORM_CD");
        var vFormVer = dts_AttachDocHistory.getCellData(cmb_AttachDoc.getSelectedIndex() + 1, "FORM_VER");
        var vAcptTpCd = dts_AttachDocHistory.getCellData(cmb_AttachDoc.getSelectedIndex() + 1, "DISCLS_ACPT_TP_CD");
        var vProcsStatCd = dts_AttachDocHistory.getCellData(cmb_AttachDoc.getSelectedIndex() + 1, "PROCS_STAT_CD");
        //alert(vAcptTpCd+", "+gAcptNo +" =="+ vAcptNo  +",  "+ vDocNo);

        /*
        // 헤더 변경 : 접수번호가 다른 첨부를 선택했을때만
        if ( gAcptNo != vAcptNo  ) {
        //	&&  (vAcptTpCd == 'U' || vAcptTpCd == 'A')) {
        	frame.Provider("../").gAcptNo = vAcptNo;
        	gAcptNo = vAcptNo;
        	gDisclsDocNo = vDocNo;			
        	gAcptTpCd = vAcptTpCd;
        	txb_AcptNo.value = vAcptNo;
        	gSelectAtt = 'Y';

        	fn_OnlyHeadRead() ;
        }
        */

        // 공시처리가 완료된것은 팝업으로 그외는 뷰어 가운데로 보여줌 
        // 2008.08.12 인수테스트시 : 김재홍, 허기영, 유재숙 합의함
        //alert('atc='+gChangeCnt +', '+gOpenAcptNo +', '+ gAcptNo +', '+gOpenDocNo +', '+vDocNo );

        if (vProcsStatCd == '30' || vProcsStatCd == '35' || vProcsStatCd == '40') {
            if (scwin.gOpenAcptNo != vAcptNo || scwin.gOpenDocNo != vDocNo &&
                scwin.gChangeCnt > 0) {
                scwin.fn_getDocHtmlURLPopup(vAcptNo, vDocNo, vFormCd, vFormVer, scwin.gLangTpCd, scwin.gSubmitSysTp);
            }
        } else {
            scwin.fn_getProcObjYn(); // 처리버튼 생성유무
            //fn_getDocHtmlURL(vAcptNo, vDocNo, vFormCd, vFormVer);

            // 본문 및 첨부 모두  미처리이므로 첨부문서 선택시 팝업으로 열기 : 2008.08.20 수정
            if (scwin.gProcsStatCd == '00' || scwin.gProcsStatCd == '01' || scwin.gProcsStatCd == '02' ||
                scwin.gProcsStatCd == '10' || scwin.gProcsStatCd == '15' || scwin.gProcsStatCd == '20') {
                // 팀장 : 승인단계	

                // 헤더 변경 : 접수번호가 다른 첨부를 선택했을때만
                if (scwin.gAcptNo != vAcptNo) {
                    //	&&  (vAcptTpCd == 'U' || vAcptTpCd == 'A')) {
                    $c.frame.path("../").scwin.gAcptNo = vAcptNo;
                    scwin.gAcptNo = vAcptNo;
                    scwin.gDisclsDocNo = vDocNo;
                    scwin.gAcptTpCd = vAcptTpCd;
                    txb_AcptNo.setValue(vAcptNo);
                    scwin.gSelectAtt = 'Y';
                    scwin.fn_OnlyHeadRead();
                }
                scwin.fn_getDocHtmlURLPopup(vAcptNo, vDocNo, vFormCd, vFormVer, scwin.gLangTpCd, scwin.gSubmitSysTp);
            } else {
                scwin.fn_getDocHtmlURL(vAcptNo, vDocNo, vFormCd, vFormVer, scwin.gLangTpCd, scwin.gSubmitSysTp);
            }
        }
        scwin.setComboValue(cmb_maindoc, '', "DOC_NO");
    }
};
